// Approximate hub indices by visual center (0-based among 31):
// 0: central-south, 2: central (Isfahan/Yazd), 5: north-central, etc.
// We highlight by index; visual positions for pulse nodes are in SVG coords.
export const HUB_INDICES: Record<MapVariant, number[]> = {
  network: [16, 26, 18], // تهران (16)، خراسان رضوی/مشهد (26)، آذربایجان شرقی/تبریز (18)
  minimal: [16],
  territory: [],
};

// Pulse node positions in viewBox 0 0 753 685 coords (۳ شهر روشن در بخش مرئی نقشه: تهران با نقطه بزرگتر، مشهد و تبریز)
export const HUB_NODES: { x: number; y: number; label: string; isCapital?: boolean }[] = [
  { x: 272, y: 251, label: 'تهران', isCapital: true },
  { x: 574, y: 218, label: 'مشهد' },
  { x: 167, y: 168, label: 'تبریز' },
];

const CONNECTIONS: [number, number][] = [[0, 1], [0, 2]];

export default function IranMap({ variant = 'network', className = '' }: { variant?: MapVariant; className?: string }) {
  const hubs = new Set(HUB_INDICES[variant]);
  const isTerritory = variant === 'territory';
  return (
    <div className={className}>
      <svg viewBox="0 0 753 685" fill="none" xmlns="http://www.w3.org/2000/svg" className="w-full h-full" aria-hidden="true" role="img">
        {/* provinces — بلر شیشه‌ای اختصاصی مستقیماً روی تک‌تک شهرها/استان‌ها */}
        {PROVINCE_DS.map((d, i) => {
          const isHub = hubs.has(i);
          const stroke = isHub && variant !== 'territory' ? 'var(--color-secondary-500)' : 'rgba(255,255,255,0.12)';
          const sw = isHub ? 1.6 : 1;
          return (
            <g key={i}>
              {/* لایه پایه: اعمال افکت بلر و پس‌زمینه به میزان یکسان روی تمام شهرها چه فعال چه غیرفعال */}
              <path
                d={d}
                fill={isTerritory ? 'rgba(255,255,255,0.07)' : '#1E2351'}
                stroke={stroke}
                strokeWidth={sw}
                strokeLinejoin="round"
                strokeLinecap="round"
                style={{
                  backdropFilter: 'blur(3px)',
                  WebkitBackdropFilter: 'blur(3px)',
                }}
              />
              {/* درخشش و های‌لایت شهرهای فعال (هاب‌ها) روی لایه پایه */}
              {isHub && (
                <path
                  d={d}
                  fill={variant === 'minimal' ? 'var(--color-secondary-500)' : 'rgba(211, 176, 90, 0.22)'}
                  stroke="var(--color-secondary-500)"
                  strokeWidth={sw}
                  strokeLinejoin="round"
                  strokeLinecap="round"
                  style={{
                    backdropFilter: 'blur(3px)',
                    WebkitBackdropFilter: 'blur(3px)',
                  }}
                />
              )}
            </g>
          );
        })}
        {/* network connections با جریان متحرک داده */}
        {variant === 'network' && CONNECTIONS.map(([a,b], idx) => {
          const pa = HUB_NODES[a]; const pb = HUB_NODES[b];
          return (
            <line
              key={idx}
              x1={pa.x}
              y1={pa.y}
              x2={pb.x}
              y2={pb.y}
              stroke="var(--color-secondary-500)"
              strokeWidth={2.4}
              strokeDasharray="6 8"
              strokeLinecap="round"
              opacity={0.65}
            >
              <animate attributeName="stroke-dashoffset" from="28" to="0" dur="2s" repeatCount="indefinite" />
            </line>
          );
        })}
        {/* pulse nodes — بازطراحی مدرن بیکن راداری با موج‌های متحدالمرکز و هسته شفاف */}
        {variant === 'network' && HUB_NODES.map((n, idx) => (
          <g key={idx} className="infra-node">
            {/* موج راداری اول */}
            <circle cx={n.x} cy={n.y} r={n.isCapital ? 8 : 5.5} fill="none" stroke="var(--color-secondary-500)" strokeWidth={1.8}>
              <animate attributeName="r" from={n.isCapital ? '8' : '5.5'} to={n.isCapital ? '32' : '24'} dur="2.4s" begin={`${idx * 0.45}s`} repeatCount="indefinite" />
              <animate attributeName="opacity" from="0.75" to="0" dur="2.4s" begin={`${idx * 0.45}s`} repeatCount="indefinite" />
            </circle>
            {/* موج راداری دوم متناوب */}
            <circle cx={n.x} cy={n.y} r={n.isCapital ? 8 : 5.5} fill="none" stroke="var(--color-secondary-400)" strokeWidth={1.2}>
              <animate attributeName="r" from={n.isCapital ? '8' : '5.5'} to={n.isCapital ? '20' : '15'} dur="2.4s" begin={`${idx * 0.45 + 0.6}s`} repeatCount="indefinite" />
              <animate attributeName="opacity" from="0.6" to="0" dur="2.4s" begin={`${idx * 0.45 + 0.6}s`} repeatCount="indefinite" />
            </circle>
            {/* هاله نور پس‌زمینه نقطه */}
            <circle cx={n.x} cy={n.y} r={n.isCapital ? 13 : 9} fill="var(--color-secondary-500)" opacity={0.3} />
            {/* هسته اصلی نقطه با بوردر شارپ سفید (تهران بزرگ‌تر و برجسته) */}
            <circle cx={n.x} cy={n.y} r={n.isCapital ? 8 : 5.5} fill="var(--color-secondary-500)" stroke="#ffffff" strokeWidth={n.isCapital ? 2 : 1.5} />
            {/* درخشش مرکز نقطه */}
            <circle cx={n.x} cy={n.y} r={n.isCapital ? 3 : 2} fill="#ffffff" />
          </g>
        ))}
        {variant === 'minimal' && (
          <g className="infra-node">
            <circle cx={HUB_NODES[0].x} cy={HUB_NODES[0].y} r={8} fill="none" stroke="var(--color-secondary-500)" strokeWidth={1.8}>
              <animate attributeName="r" from="8" to="30" dur="2.2s" repeatCount="indefinite" />
              <animate attributeName="opacity" from="0.7" to="0" dur="2.2s" repeatCount="indefinite" />
            </circle>
            <circle cx={HUB_NODES[0].x} cy={HUB_NODES[0].y} r={7} fill="var(--color-secondary-500)" stroke="#ffffff" strokeWidth={1.8} />
            <circle cx={HUB_NODES[0].x} cy={HUB_NODES[0].y} r={2.5} fill="#ffffff" />
          </g>
        )}
      </svg>
    </div>
  );
}
